1	package review
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12		"time"
13	
14		"github.com/entireio/cli/cmd/entire/cli/agent"
15		agenttypes "github.com/entireio/cli/cmd/entire/cli/agent/types"
16		"github.com/entireio/cli/cmd/entire/cli/paths"
17		reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
18		"github.com/entireio/cli/cmd/entire/cli/session"
19	)
20	
21	const localReviewManifestVersion = 1
22	
23	var reviewAgentByType = agent.GetByAgentType // overridable in tests without mutating the global agent registry
24	
25	// LocalReviewManifest records one local `entire review` invocation. It lets
26	// `entire review --fix <session-id>` use a single session id as the lookup
27	// handle while still loading sibling agent outputs from the same review run.
28	type LocalReviewManifest struct {
29		Version         int              `json:"version"`
30		WorktreePath    string           `json:"worktree_path"`
31		CreatedAt       time.Time        `json:"created_at"`
32		StartingSHA     string           `json:"starting_sha,omitempty"`
33		Sources         []ManifestSource `json:"sources"`
34		AggregateOutput string           `json:"aggregate_output,omitempty"`
35	}
36	
37	type ManifestSource struct {
38		SessionID string `json:"session_id"`
39		Agent     string `json:"agent"`
40		Label     string `json:"label"`
41		Status    string `json:"status,omitempty"`
42		Output    string `json:"output,omitempty"`
43	}
44	
45	func buildLocalReviewManifestFromSummary(
46		worktreeRoot string,
47		headSHA string,
48		summary reviewtypes.RunSummary,
49		states []*session.State,
50		aggregateOutput string,
51	) LocalReviewManifest {
52		manifest := LocalReviewManifest{
53			Version:         localReviewManifestVersion,
54			WorktreePath:    worktreeRoot,
55			CreatedAt:       summary.StartedAt,
56			StartingSHA:     headSHA,
57			AggregateOutput: strings.TrimSpace(aggregateOutput),
58		}
59		usedSessions := map[string]bool{}
60		for _, run := range summary.AgentRuns {
61			st := matchReviewSessionState(worktreeRoot, headSHA, summary.StartedAt, run.Name, states, usedSessions)
62			if st == nil || st.SessionID == "" {
63				continue
64			}
65			usedSessions[st.SessionID] = true
66			manifest.Sources = append(manifest.Sources, ManifestSource{
67				SessionID: st.SessionID,
68				Agent:     run.Name,
69				Label:     labelForReviewAgent(run.Name),
70				Status:    run.Status.String(),
71				Output:    agentRunOutput(run),
72			})
73		}
74		return manifest
75	}
76	
77	func localReviewManifestFromCurrentState(
78		ctx context.Context,
79		worktreeRoot string,
80		headSHA string,
81		summary reviewtypes.RunSummary,
82		aggregateOutput string,
83	) (LocalReviewManifest, error) {
84		store, err := session.NewStateStore(ctx)
85		if err != nil {
86			return LocalReviewManifest{}, fmt.Errorf("create session state store: %w", err)
87		}
88		states, err := store.List(ctx)
89		if err != nil {
90			return LocalReviewManifest{}, fmt.Errorf("list session states: %w", err)
91		}
92		return buildLocalReviewManifestFromSummary(worktreeRoot, headSHA, summary, states, aggregateOutput), nil
93	}
94	
95	func hydrateReviewSummaryTokensFromCurrentState(
96		ctx context.Context,
97		worktreeRoot string,
98		headSHA string,
99		summary reviewtypes.RunSummary,
100	) (reviewtypes.RunSummary, error) {
101		store, err := session.NewStateStore(ctx)
102		if err != nil {
103			return summary, fmt.Errorf("create session state store: %w", err)
104		}
105		states, err := store.List(ctx)
106		if err != nil {
107			return summary, fmt.Errorf("list session states: %w", err)
108		}
109		return hydrateReviewSummaryTokensFromStates(ctx, worktreeRoot, headSHA, summary, states), nil
110	}
111	
112	func hydrateReviewAgentRunTokensFromCurrentState(
113		ctx context.Context,
114		worktreeRoot string,
115		headSHA string,
116		run reviewtypes.AgentRun,
117	) (reviewtypes.AgentRun, error) {
118		store, err := session.NewStateStore(ctx)
119		if err != nil {
120			return run, fmt.Errorf("create session state store: %w", err)
121		}
122		states, err := store.List(ctx)
123		if err != nil {
124			return run, fmt.Errorf("list session states: %w", err)
125		}
126		return hydrateReviewAgentRunTokensFromStates(ctx, worktreeRoot, headSHA, run, states), nil
127	}
128	
129	func hydrateReviewAgentRunTokensFromStates(
130		ctx context.Context,
131		worktreeRoot string,
132		headSHA string,
133		run reviewtypes.AgentRun,
134		states []*session.State,
135	) reviewtypes.AgentRun {
136		st := matchReviewSessionState(worktreeRoot, headSHA, run.StartedAt, run.Name, states, map[string]bool{})
137		if st == nil || st.SessionID == "" {
138			return run
139		}
140		tokens := reviewTokensFromTokenUsage(reviewTokenUsageForSession(ctx, st))
141		if tokens.In == 0 && tokens.Out == 0 {
142			return run
143		}
144		run.Tokens = tokens
145		return run
146	}
147	
148	func hydrateReviewSummaryTokensFromStates(
149		ctx context.Context,
150		worktreeRoot string,
151		headSHA string,
152		summary reviewtypes.RunSummary,
153		states []*session.State,
154	) reviewtypes.RunSummary {
155		usedSessions := map[string]bool{}
156		for i, run := range summary.AgentRuns {
157			st := matchReviewSessionState(worktreeRoot, headSHA, summary.StartedAt, run.Name, states, usedSessions)
158			if st == nil || st.SessionID == "" {
159				continue
160			}
161			usedSessions[st.SessionID] = true
162			tokens := reviewTokensFromTokenUsage(reviewTokenUsageForSession(ctx, st))
163			if tokens.In == 0 && tokens.Out == 0 {
164				continue
165			}
166			summary.AgentRuns[i].Tokens = tokens
167		}
168		return summary
169	}
170	
171	func reviewTokenUsageForSession(ctx context.Context, st *session.State) *agent.TokenUsage {
172		if st == nil {
173			return nil
174		}
175		if hasReviewTokenUsageData(st.TokenUsage) {
176			return st.TokenUsage
177		}
178		if st.TranscriptPath == "" || st.AgentType == "" {
179			return nil
180		}
181		ag, err := reviewAgentByType(st.AgentType)
182		if err != nil {
183			return nil
184		}
185		transcript, err := os.ReadFile(st.TranscriptPath)
186		if err != nil {
187			return nil
188		}
189		return agent.CalculateTokenUsage(ctx, ag, transcript, st.CheckpointTranscriptStart, reviewSubagentsDir(st))
190	}
191	
192	func reviewSubagentsDir(st *session.State) string {
193		if st == nil || st.TranscriptPath == "" || st.SessionID == "" {
194			return ""
195		}
196		return filepath.Join(filepath.Dir(st.TranscriptPath), st.SessionID, "subagents")
197	}
198	
199	func reviewTokensFromTokenUsage(usage *agent.TokenUsage) reviewtypes.Tokens {
200		if usage == nil {
201			return reviewtypes.Tokens{}
202		}
203		tokens := reviewtypes.Tokens{
204			In:  usage.InputTokens + usage.CacheCreationTokens + usage.CacheReadTokens,
205			Out: usage.OutputTokens,
206		}
207		subagentTokens := reviewTokensFromTokenUsage(usage.SubagentTokens)
208		tokens.In += subagentTokens.In
209		tokens.Out += subagentTokens.Out
210		return tokens
211	}
212	
213	func hasReviewTokenUsageData(usage *agent.TokenUsage) bool {
214		if usage == nil {
215			return false
216		}
217		if usage.InputTokens != 0 || usage.CacheCreationTokens != 0 || usage.CacheReadTokens != 0 || usage.OutputTokens != 0 || usage.APICallCount != 0 {
218			return true
219		}
220		return hasReviewTokenUsageData(usage.SubagentTokens)
221	}
222	
223	func matchReviewSessionState(
224		worktreeRoot string,
225		headSHA string,
226		runStartedAt time.Time,
227		agentName string,
228		states []*session.State,
229		used map[string]bool,
230	) *session.State {
231		wantAgentType := agentTypeForReviewAgent(agentName)
232		var best *session.State
233		for _, st := range states {
234			if st == nil || used[st.SessionID] || st.Kind != session.KindAgentReview {
235				continue
236			}
237			if worktreeRoot != "" && st.WorktreePath != "" && st.WorktreePath != worktreeRoot {
238				continue
239			}
240			if headSHA != "" && st.BaseCommit != "" && st.BaseCommit != headSHA {
241				continue
242			}
243			if !runStartedAt.IsZero() && st.StartedAt.Before(runStartedAt.Add(-5*time.Second)) {
244				continue
245			}
246			if wantAgentType != "" && st.AgentType != "" && st.AgentType != wantAgentType {
247				continue
248			}
249			if best == nil || st.StartedAt.After(best.StartedAt) {
250				best = st
251			}
252		}
253		return best
254	}
255	
256	func agentTypeForReviewAgent(agentName string) agenttypes.AgentType {
257		ag, err := agent.Get(agenttypes.AgentName(agentName))
258		if err != nil {
259			return ""
260		}
261		return ag.Type()
262	}
263	
264	func labelForReviewAgent(agentName string) string {
265		if typ := agentTypeForReviewAgent(agentName); typ != "" {
266			return string(typ)
267		}
268		return agentName
269	}
270	
271	func agentRunOutput(run reviewtypes.AgentRun) string {
272		if narrative := joinAssistantText(run.Buffer); narrative != "" {
273			return narrative
274		}
275		if run.Err != nil {
276			return "Failed: " + run.Err.Error()
277		}
278		return ""
279	}
280	
281	func writeLocalReviewManifest(ctx context.Context, manifest LocalReviewManifest) error {
282		if len(manifest.Sources) == 0 {
283			return errors.New("review manifest has no sources")
284		}
285		if manifest.Version == 0 {
286			manifest.Version = localReviewManifestVersion
287		}
288		if manifest.CreatedAt.IsZero() {
289			manifest.CreatedAt = time.Now()
290		}
291	
292		dir, err := localReviewManifestDir(ctx)
293		if err != nil {
294			return err
295		}
296		if err := os.MkdirAll(dir, 0o700); err != nil {
297			return fmt.Errorf("create review manifest dir: %w", err)
298		}
299	
300		b, err := json.MarshalIndent(manifest, "", "  ")
301		if err != nil {
302			return fmt.Errorf("encode review manifest: %w", err)
303		}
304		path := filepath.Join(dir, localReviewManifestFilename(manifest))
305		if err := os.WriteFile(path, b, 0o600); err != nil {
306			return fmt.Errorf("write review manifest: %w", err)
307		}
308		return nil
309	}
310	
311	func resolveLocalReviewManifestBySessionID(ctx context.Context, worktreeRoot, sessionID string) (LocalReviewManifest, ManifestSource, error) {
312		manifests, err := loadLocalReviewManifests(ctx, worktreeRoot)
313		if err != nil {
314			return LocalReviewManifest{}, ManifestSource{}, err
315		}
316	
317		var (
318			matches       []LocalReviewManifest
319			sourceMatches []ManifestSource
320		)
321		for _, manifest := range manifests {
322			for _, source := range manifest.Sources {
323				if source.SessionID == sessionID || strings.HasPrefix(source.SessionID, sessionID) {
324					matches = append(matches, manifest)
325					sourceMatches = append(sourceMatches, source)
326					break
327				}
328			}
329		}
330		switch len(matches) {
331		case 0:
332			return LocalReviewManifest{}, ManifestSource{}, fmt.Errorf("review session %q not found", sessionID)
333		case 1:
334			return matches[0], sourceMatches[0], nil
335		default:
336			return LocalReviewManifest{}, ManifestSource{}, fmt.Errorf("review session prefix %q is ambiguous", sessionID)
337		}
338	}
339	
340	func loadLocalReviewManifests(ctx context.Context, worktreeRoot string) ([]LocalReviewManifest, error) {
341		dir, err := localReviewManifestDir(ctx)
342		if err != nil {
343			return nil, err
344		}
345		entries, err := os.ReadDir(dir)
346		if errors.Is(err, os.ErrNotExist) {
347			return nil, nil
348		}
349		if err != nil {
350			return nil, fmt.Errorf("read review manifest dir: %w", err)
351		}
352	
353		manifests := make([]LocalReviewManifest, 0, len(entries))
354		for _, entry := range entries {
355			if entry.IsDir() || filepath.Ext(entry.Name()) != ".json" {
356				continue
357			}
358			b, readErr := os.ReadFile(filepath.Join(dir, entry.Name())) //nolint:gosec // entry names come directly from os.ReadDir(dir).
359			if readErr != nil {
360				return nil, fmt.Errorf("read review manifest %s: %w", entry.Name(), readErr)
361			}
362			var manifest LocalReviewManifest
363			if err := json.Unmarshal(b, &manifest); err != nil {
364				return nil, fmt.Errorf("decode review manifest %s: %w", entry.Name(), err)
365			}
366			if worktreeRoot != "" && manifest.WorktreePath != "" && manifest.WorktreePath != worktreeRoot {
367				continue
368			}
369			manifests = append(manifests, manifest)
370		}
371		sort.SliceStable(manifests, func(i, j int) bool {
372			return manifests[i].CreatedAt.After(manifests[j].CreatedAt)
373		})
374		return manifests, nil
375	}
376	
377	func localReviewManifestDir(ctx context.Context) (string, error) {
378		worktreeRoot, err := paths.WorktreeRoot(ctx)
379		if err != nil {
380			return "", fmt.Errorf("resolve worktree root: %w", err)
381		}
