13	// TestRunMulti_BothSucceed verifies that two agents that complete cleanly
14	// produce two AgentRuns with status Succeeded, that all events from both
15	// agents reach the sink, and that sinks see RunFinished exactly once.
16	func TestRunMulti_BothSucceed(t *testing.T) {
17		t.Parallel()
18		eventsA := []reviewtypes.Event{
19			reviewtypes.Started{},
20			reviewtypes.AssistantText{Text: "agent-a review"},
21			reviewtypes.Finished{Success: true},
