29		rb := &stubReviewer{name: "agent-b", events: eventsB}
30		rec := &stubSinkRecorder{}
31	
32		summary, err := RunMulti(context.Background(), []reviewtypes.AgentReviewer{ra, rb}, reviewtypes.RunConfig{}, []reviewtypes.Sink{rec})
33		if err != nil {
34			t.Fatalf("expected nil error, got %v", err)
35		}
36		if summary.Cancelled {
37			t.Error("expected Cancelled=false")
38		}
39		if len(summary.AgentRuns) != 2 {
40			t.Fatalf("expected 2 AgentRuns, got %d", len(summary.AgentRuns))
